const body = $input.first().json.body;

// CONFIG: your own accounts, so the workflow never answers itself.
const OUR_PAGE_ID = 'YOUR_PAGE_ID';
const OUR_IG_USERNAME = 'YOUR_IG_USERNAME';
const OUR_NAMES = ['your store name', 'your_ig_username'];
// CONFIG: Graph API version. This is the only place it is set. Use a currently supported version.
const GRAPH_API_VERSION = 'v24.0';
// CONFIG: product assumed when a comment names none. Leave empty to answer in general terms or point to the relevant product page.
// Use the name of one of the products listed in Parse agent decision (for example 'Product A').
const DEFAULT_PRODUCT = '';
// CONFIG: comments longer than this are cut before they reach the model.
const MAX_COMMENT_CHARS = 1000;

let platform = 'unknown';
let comment_id = '';
let media_id = '';
let author = '';
let author_id = '';
let message = '';
let timestamp = '';

// First deduplication layer: workflow static data.
const staticData = $getWorkflowStaticData('global');
if (!staticData.processedComments) staticData.processedComments = {};

// Keep only the last 500 IDs.
const ids = Object.keys(staticData.processedComments);
if (ids.length > 500) {
  ids.slice(0, ids.length - 500).forEach((id) => delete staticData.processedComments[id]);
}

try {
  const entry = body?.entry?.[0];
  const change = entry?.changes?.[0];
  const value = change?.value;

  if (!value) {
    return [{ json: { skip: true, reason: 'No change value' } }];
  }

  if (body.object === 'instagram' && change?.field === 'comments') {
    platform = 'instagram';
    comment_id = value.id || '';
    media_id = value.media?.id || '';
    author = value.from?.username || 'Instagram user';
    author_id = String(value.from?.id || '');
    message = value.text || '';
    timestamp = entry.time || new Date().toISOString();

    if (OUR_NAMES.includes(author.toLowerCase()) || author === OUR_IG_USERNAME) {
      return [{ json: { skip: true, reason: 'Own Instagram comment' } }];
    }
  } else if (body.object === 'page' && change?.field === 'feed') {
    if (value.item !== 'comment' || value.verb !== 'add') {
      return [{ json: { skip: true, reason: 'Not a new comment' } }];
    }

    platform = 'facebook';
    comment_id = value.comment_id || '';
    media_id = value.post_id || '';
    author = value.from?.name || 'Facebook user';
    author_id = String(value.from?.id || '');
    message = value.message || '';
    timestamp = value.created_time || new Date().toISOString();

    if (author_id === OUR_PAGE_ID || OUR_NAMES.includes(author.toLowerCase())) {
      return [{ json: { skip: true, reason: 'Own Facebook comment' } }];
    }
  } else {
    return [{ json: { skip: true, reason: 'Unsupported event: ' + body?.object + '/' + change?.field } }];
  }

  if (!message || !comment_id) {
    return [{ json: { skip: true, reason: 'Empty message or no comment_id' } }];
  }

  if (staticData.processedComments[comment_id]) {
    return [{ json: { skip: true, reason: 'Duplicate comment_id: ' + comment_id } }];
  }
  staticData.processedComments[comment_id] = Date.now();

  message = String(message).slice(0, MAX_COMMENT_CHARS);

  return [{
    json: { skip: false, platform, comment_id, media_id, author, author_id, message, timestamp, graph_version: GRAPH_API_VERSION, default_product: DEFAULT_PRODUCT }
  }];
} catch (e) {
  return [{ json: { skip: true, reason: 'Parse error: ' + e.message } }];
}

// ---------------------------------------------------------------------------
// CONFIG: edit these constants before going live.
// ---------------------------------------------------------------------------
const SUPPORT_EMAIL = 'YOUR_SUPPORT_EMAIL';
const STORE_URL = 'YOUR_STORE_URL';
// Hosts that may appear in a public reply. A model reply with any other link is not posted.
const ALLOWED_REPLY_HOSTS = ['your-store.example'];
// STRICT_MODE (off by default): also hide criticism that contains no question.
// Hiding consumer criticism can create legal and reputational risk. Read the README first.
const STRICT_MODE = false;
// When a criticism stays visible, post one short polite reply that invites the person to contact support.
const REPLY_TO_CRITICISM = true;
// Transparency: public replies end with this mention.
const AI_DISCLOSURE_ENABLED = true;
const AI_DISCLOSURE_TEXT = 'Reply from our AI assistant';
// Which product to assume when a comment names none is set once, as DEFAULT_PRODUCT in Extract comment (empty by default).
const PRODUCTS = [
  { name: 'Product A', match: /product a/i, url: 'YOUR_PRODUCT_A_URL' },
  { name: 'Product B', match: /product b/i, url: 'YOUR_PRODUCT_B_URL' },
  { name: 'Product C', match: /product c/i, url: 'YOUR_PRODUCT_C_URL' }
];
// Meta user IDs whose comments are always hidden.
const BLOCKED_AUTHOR_IDS = [];
// Competitor names and domains: a mention together with a link is hidden as a competitor ad.
const COMPETITOR_NAMES = ['example-competitor'];
const COMPETITOR_DOMAINS = ['example-competitor.test'];
// Safety terms (lowercase fragments). A match is never hidden or ignored: escalated with a neutral reply.
const SAFETY_KEYWORDS = ['unsafe', 'dangerous', 'hazard', 'injured', 'injury', 'hospital', 'ambulance', 'poison', 'toxic', 'caught fire', 'harmful', 'choking', 'emergency'];
// Optional fixed answers: { pattern: /regex/i, message: '...', reason: '...' }
const FAQ_RULES = [];

const SAFETY_REPLY = `Hello, thank you for letting us know. Please contact us at ${SUPPORT_EMAIL} so our team can look into this right away.`;
const CRITICISM_REPLY = `Hello, we are sorry to hear that. Please contact us at ${SUPPORT_EMAIL} so we can look into it.`;
const SUPPORT_REPLY = `Hello, I am sorry about that. Could you email us at ${SUPPORT_EMAIL} with your order number so we can check quickly?`;
const QUESTION_FALLBACK_REPLY = `Hello, thanks for your question. You will find the details on ${STORE_URL}, or you can write to us at ${SUPPORT_EMAIL}.`;
const HIDE_CATEGORIES = ['abuse', 'spam', 'scam_link', 'competitor_ad', 'personal_data'];

// ---------------------------------------------------------------------------
// Input
// ---------------------------------------------------------------------------
const ctx = $('Fetch post context').first().json;
const commentText = String(ctx.message || '');
const normalized = commentText.toLowerCase().trim();
const modelOut = $input.first()?.json?.output ?? $input.first()?.json?.text ?? '';
const rawOut = (typeof modelOut === 'string' ? modelOut : JSON.stringify(modelOut)).trim();

// ---------------------------------------------------------------------------
// Pattern lists
// ---------------------------------------------------------------------------
const abusePatterns = [
  /\b(?:idiots?|morons?|imbeciles?|scumbags?|assholes?|bastards?|losers?)\b/i,
  /\bshut (?:up|your mouth)\b|\bgo to hell\b|\bkill yourself\b/i,
  /\bf+u+c+k+\s+(?:you|off)\b/i,
  /\byou(?:'re|’re| are)\s+(?:all\s+|so\s+)?(?:stupid|dumb)\b/i
];
const spamPatterns = [
  /\bfollow\s+(?:me|us|back)\b|\bf4f\b|\bl4l\b/i,
  /\bcheck\s+(?:out\s+)?my\s+(?:profile|page|bio)\b|\blink\s+in\s+(?:my\s+)?bio\b/i,
  /\b(?:dm|message)\s+me\s+for\b/i,
  /\bmake\s+money\b|\bearn\s+\$?\d+\s+(?:a|per)\s+(?:day|week|hour)\b|\bwork\s+from\s+home\b/i,
  /\bcrypto\b|\bforex\b|\bbuy\s+followers\b|\bfree\s+followers\b/i
];
const urlPattern = /\b(?:https?:\/\/|www\.)\S+|\b[a-z0-9-]+(?:\.[a-z0-9-]+)*\.(?:com|net|org|io|co|shop|store|xyz|top|click|link|ly|me|info|biz|site|online)\b/i;
const phishingPatterns = [
  /\bverify\s+(?:your\s+)?account\b|\baccount\s+(?:is\s+)?(?:suspended|locked|blocked)\b/i,
  /\bclaim\s+(?:your\s+)?(?:prize|reward|gift)\b|\byou(?:'ve|’ve|\s+have)?\s+won\b|\bgift\s+card\b/i,
  /\bwallet\b|\bseed\s+phrase\b|\bpassword\b|\blog\s?in\s+(?:here|now)\b/i,
  /\b(?:bit\.ly|tinyurl\.com|t\.co|goo\.gl|ow\.ly|is\.gd|cutt\.ly|rb\.gy)\//i
];
const emailPattern = /[\w.+-]+@[\w-]+(?:\.[\w-]+)+/i;
const addressPattern = /\b\d{1,5}\s+[a-z0-9.'-]+(?:\s+[a-z0-9.'-]+){0,3}\s+(?:street|st|avenue|ave|road|rd|lane|ln|drive|dr|boulevard|blvd|court|ct)\b/i;
const orderNumberPatterns = [/\border\s*(?:no\.?|number|num|id|#)?\s*[:#]?\s*#?\d{4,}\b/i, /#\d{4,}\b/];

const criticismPatterns = [
  /doesn['’]?t work|does not work|didn['’]?t work|not working|stopped working|won['’]?t work/i,
  /\bwaste of (?:money|time)\b/i,
  /misleading|false advertising|not as described/i,
  /fake reviews?/i,
  /\bscam|\bfraud|rip[\s-]?off|\bthie(?:f|ves)\b|\bliars?\b|\blying\b/i,
  /don['’]?t buy|do not buy|never buy/i,
  /disappoint|useless|\bterrible\b|\bawful\b|\bgarbage\b|\bpathetic\b|poor quality/i,
  /\bshame on\b|\bdisgrace/i
];
const supportPatterns = [
  /\border\b|\borders\b/i,
  /deliver|shipping|shipped|parcel|package|tracking/i,
  /(?:haven['’]?t|have not|didn['’]?t|did not)\s+(?:received|got|arrive)/i,
  /refund|\breturn|exchange|warranty|guarantee|invoice/i,
  /\bbroken\b|\bbroke\b|damaged|defect/i,
  /\bsupport\b/i
];
const questionPatterns = [
  /\?/,
  /\b(?:how|why|what|which|when|where|who)\b/i,
  /\b(?:can|could|do|does|is|are|will)\s+(?:you|i|we|it|they|there)\b/i,
  /\bplease\b|\bpls\b/i,
  /\bprice|\bcost\b|\bavailab|in stock/i
];
const purchasePatterns = [
  /how.*\border\b|\bto order\b|\border\s+(?:it|one|this|them)\b/i,
  /\bbuy\b|\bpurchase\b|\bprice|how much|\bcost\b/i,
  /where can i (?:get|find|buy|order)/i,
  /i want (?:it|one|this)/i
];

const hasAny = (patterns) => patterns.some((p) => p.test(normalized));
const criticism = hasAny(criticismPatterns);
const question = hasAny(questionPatterns);
const support = hasAny(supportPatterns);
const purchase = hasAny(purchasePatterns) && !/don['’]?t buy|do not buy|never buy/i.test(normalized);
const safetyConcern = SAFETY_KEYWORDS.some((k) => normalized.includes(k.toLowerCase()));

function hasPhone() {
  const matches = commentText.match(/\+?\d[\d\s().-]{7,}\d/g) || [];
  return matches.some((m) => {
    const digits = m.replace(/\D/g, '').length;
    return digits >= 9 && digits <= 15;
  });
}

const competitorDomainMentioned = COMPETITOR_DOMAINS.some((d) => normalized.includes(d.toLowerCase()));
const urlPresent = urlPattern.test(normalized) || competitorDomainMentioned;
const competitorNameMentioned = COMPETITOR_NAMES.length > 0 && new RegExp('(?:' + COMPETITOR_NAMES.map((n) => n.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|') + ')', 'i').test(normalized);

// ---------------------------------------------------------------------------
// Decisions
// ---------------------------------------------------------------------------
const mk = (action, message, reason, category, extra) => ({ action, message, reason, category, ...(extra || {}) });
const hide = (category, reason) => mk('hide', null, reason, category);
const escalate = (reason, category, message) => mk('escalate', message || null, reason, category);

function hardHide() {
  if (BLOCKED_AUTHOR_IDS.includes(String(ctx.author_id || ''))) return hide('abuse', 'blocked author: always hidden');
  if (emailPattern.test(commentText) || hasPhone() || addressPattern.test(commentText) || orderNumberPatterns.some((p) => p.test(commentText))) {
    return hide('personal_data', 'personal data published in a comment: hidden, follow up privately');
  }
  if (urlPresent && phishingPatterns.some((p) => p.test(normalized))) return hide('scam_link', 'suspicious link (phishing or scam pattern)');
  if (competitorDomainMentioned || (urlPresent && competitorNameMentioned)) return hide('competitor_ad', 'competitor promotion with a link');
  if (hasAny(spamPatterns)) return hide('spam', 'spam or unsolicited promotion');
  if (hasAny(abusePatterns)) return hide('abuse', 'insult or harassment');
  return null;
}

function criticismDecision(reason) {
  if (STRICT_MODE) return hide('criticism', 'STRICT_MODE: criticism without a question is hidden');
  return escalate(reason, 'criticism', REPLY_TO_CRITICISM ? CRITICISM_REPLY : null);
}

// Product named in the comment, else the configured default product, else null (answer in general terms).
function productFor() {
  const named = PRODUCTS.find((p) => p.match.test(normalized));
  if (named) return named;
  const wanted = String(ctx.default_product || '').trim().toLowerCase();
  return (wanted && PRODUCTS.find((p) => p.name.toLowerCase() === wanted)) || null;
}

// Rules only, used when the model output is unusable.
function ruleDecision(reason) {
  if (criticism && !question) return criticismDecision(reason || 'criticism without a question');
  if (purchase) {
    const product = productFor();
    if (!product) return mk('reply', QUESTION_FALLBACK_REPLY, reason || 'purchase question, no product named', 'question');
    return mk('reply', `Hello, you can find ${product.name} here: ${product.url}`, reason || `purchase question about ${product.name}`, 'question');
  }
  for (const rule of FAQ_RULES) {
    if (rule.pattern.test(normalized)) return mk('reply', rule.message, reason || rule.reason || 'matched FAQ rule', 'question');
  }
  if (support) return mk('reply', SUPPORT_REPLY, reason || 'support request', 'support');
  if (question) return mk('reply', QUESTION_FALLBACK_REPLY, reason || 'question without a model answer', 'question');
  return mk('ignore', null, reason || 'nothing to act on', 'neutral');
}

function replyIsUsable(message) {
  if (typeof message !== 'string' || message.trim().length < 8) return 'empty or too short';
  if (/\[[^\]]{1,40}\]|<[^>]{1,40}>|\bxxx\b/i.test(message)) return 'placeholder in reply';
  const hosts = (message.match(/\b(?:https?:\/\/)?(?:www\.)?[a-z0-9-]+(?:\.[a-z0-9-]+)*\.[a-z]{2,}/gi) || [])
    .map((h) => h.replace(/^https?:\/\//i, '').replace(/^www\./i, '').toLowerCase());
  const foreign = hosts.some((h) => !ALLOWED_REPLY_HOSTS.some((a) => h === a || h.endsWith('.' + a)));
  if (foreign) return 'link to a host that is not allowed';
  return null;
}

function modelDecision(m) {
  const action = ['reply', 'hide', 'ignore', 'escalate'].includes(m?.action) ? m.action : null;
  const message = typeof m?.message === 'string' ? m.message.trim() : null;
  const reason = typeof m?.reason === 'string' && m.reason.trim() ? m.reason.trim().slice(0, 200) : 'reason not given';
  const category = typeof m?.category === 'string' ? m.category.trim().toLowerCase() : 'other';
  if (!action) return ruleDecision('invalid action from model');

  // Criticism without a question is never ignored and never answered with a free-form model text.
  if (criticism && !question && action !== 'hide') return criticismDecision(reason);

  if (action === 'hide') {
    if (HIDE_CATEGORIES.includes(category)) return hide(category, reason);
    if (STRICT_MODE && criticism && !question) return hide('criticism', 'STRICT_MODE: criticism without a question is hidden');
    // The model proposed a hide outside the policy: a human looks at it, the comment stays visible.
    const msg = criticism && !question && REPLY_TO_CRITICISM ? CRITICISM_REPLY : null;
    return escalate('hide proposed outside the hide policy: kept visible. ' + reason, category === 'criticism' ? 'criticism' : 'other', msg);
  }

  if (action === 'escalate') {
    // A criticism escalated by the model gets the same polite reply as one caught by the patterns.
    // A safety category never gets it: the safety rules above decide what is said in a safety case.
    const isCriticism = category === 'criticism' || (criticism && category !== 'safety');
    return escalate(reason, category, isCriticism && REPLY_TO_CRITICISM ? CRITICISM_REPLY : null);
  }

  if (action === 'ignore') {
    if (support) return mk('reply', SUPPORT_REPLY, 'support request was not answered by the model', 'support');
    return mk('ignore', null, reason, category);
  }

  // reply
  const problem = replyIsUsable(message);
  if (problem) return ruleDecision('model reply rejected: ' + problem);
  return mk('reply', message, reason, category);
}

// ---------------------------------------------------------------------------
// JSON extraction from the model output
// ---------------------------------------------------------------------------
function tryParseCandidate(candidate) {
  if (!candidate) return null;
  const trimmed = candidate.trim();
  if (!trimmed.startsWith('{') || !trimmed.endsWith('}')) return null;
  try { return JSON.parse(trimmed); } catch { return null; }
}

function extractBalancedJsonCandidates(text) {
  const candidates = [];
  let depth = 0;
  let start = -1;
  let inString = false;
  let escaped = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (escaped) { escaped = false; continue; }
    if (ch === '\\') { escaped = true; continue; }
    if (ch === '"') { inString = !inString; continue; }
    if (inString) continue;
    if (ch === '{') { if (depth === 0) start = i; depth += 1; continue; }
    if (ch === '}') {
      if (depth === 0) continue;
      depth -= 1;
      if (depth === 0 && start !== -1) { candidates.push(text.slice(start, i + 1)); start = -1; }
    }
  }
  return candidates;
}

function parseFirstValidDecision(text) {
  const direct = tryParseCandidate(text);
  if (direct) return direct;
  const block = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (block) {
    const parsed = tryParseCandidate(block[1]);
    if (parsed) return parsed;
  }
  for (const line of text.split('\n').map((l) => l.trim()).filter((l) => l.startsWith('{') && l.endsWith('}'))) {
    const parsed = tryParseCandidate(line);
    if (parsed) return parsed;
  }
  for (const candidate of extractBalancedJsonCandidates(text)) {
    const parsed = tryParseCandidate(candidate);
    if (parsed) return parsed;
  }
  throw new Error('No valid JSON decision found in model output');
}

// ---------------------------------------------------------------------------
// Final assembly: policy order is safety, hard hide rules, then the model with rule corrections.
// ---------------------------------------------------------------------------
function finalize(d) {
  const postReply = (d.action === 'reply' || d.action === 'escalate') && typeof d.message === 'string' && d.message.trim().length > 0;
  let message = postReply ? d.message.trim() : null;
  if (postReply && AI_DISCLOSURE_ENABLED) message = message + '\n\n' + AI_DISCLOSURE_TEXT;
  return {
    action: d.action,
    message,
    reason: d.reason,
    category: d.category,
    safety_concern: !!d.safety_concern,
    post_reply: postReply,
    needs_human: d.action === 'escalate',
    comment_text: commentText,
    platform: ctx.platform,
    comment_id: ctx.comment_id,
    author: ctx.author,
    author_id: ctx.author_id,
    graph_version: ctx.graph_version
  };
}

let decision;
if (safetyConcern) {
  decision = escalate('safety concern: never hidden, escalated to a human', 'safety', SAFETY_REPLY);
  decision.safety_concern = true;
} else {
  const hard = hardHide();
  if (hard) {
    decision = hard;
  } else {
    try {
      decision = modelDecision(parseFirstValidDecision(rawOut));
    } catch (error) {
      decision = ruleDecision(`fallback after parse error: ${error.message}`);
      // A comment with real content is never silently ignored when the model output was unusable.
      const meaningfulChars = normalized.replace(/[^a-z0-9]/gi, '').length;
      if (decision.action === 'ignore' && meaningfulChars >= 4) {
        decision = escalate('human review (model output could not be parsed)', 'other', null);
      }
    }
  }
}

return [{ json: finalize(decision) }];

const item = $input.first().json;
const media_id = item.media_id;
const platform = item.platform;
// The Page token comes from an environment variable, never from the workflow text.
const token = $env.META_PAGE_TOKEN || '';
const version = item.graph_version;

let post_description = '';
let context_error = null;

if (!token) {
  context_error = 'META_PAGE_TOKEN is not set: post context not fetched';
} else {
  try {
    const field = platform === 'instagram' ? 'caption' : 'message';
    // In a Code node (Run Once for All Items) the HTTP helper is this.helpers.httpRequest.
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://graph.facebook.com/' + version + '/' + media_id,
      qs: { fields: field, access_token: token },
      json: true
    });

    post_description = response.caption || response.message || '';
    if (post_description.length > 300) {
      post_description = post_description.substring(0, 300) + '...';
    }
  } catch (e) {
    // Context stays optional, but the failure is visible in the node output.
    // The request carries the token, so it is scrubbed from the message before it is stored.
    post_description = '';
    context_error = String((e && e.message) || e).split(token).join('[token]').slice(0, 300);
  }
}

return [{
  json: {
    ...item,
    post_description,
    context_error
  }
}];

