const extracted = $('Extract comment').all();
const dedupRows = $input.all();

// Events that were already skipped upstream just pass through to the validity check.
if (extracted.length && extracted[0].json.skip === true) {
  return extracted;
}

const first = dedupRows[0]?.json || {};

// Database error: deliberate fail-open (a real comment is never lost), but flagged.
if (first.error) {
  return extracted.map((item) => ({
    json: {
      ...item.json,
      dedup_fallback: true,
      dedup_error: String(first.error.message || first.error || 'postgres dedup unavailable')
    }
  }));
}

// INSERT ... ON CONFLICT DO NOTHING RETURNING comment_id:
//   one row  -> new comment, continue
//   no row   -> duplicate, stop here
const freshIds = new Set(
  dedupRows.map((row) => row?.json?.comment_id).filter(Boolean).map(String)
);

if (freshIds.size === 0) {
  return [];
}

return extracted.filter((item) => freshIds.has(String(item.json.comment_id)));

const row = $input.first().json;
const d = $('Parse agent decision').first().json;

const comment = String(row['Comment'] || d.comment_text || '').trim();
const response = String(row['Posted reply'] || '').trim();
const status = String(row['Status'] || '').trim();
const action = String(row['Agent action'] || d.action || '').trim();
const author = String(row['Author'] || '').trim();
const platform = String(row['Platform'] || '').trim();
const comment_id = String(d.comment_id || row['Comment ID'] || '').trim();
const category = String(d.category || '').trim();
const lower = comment.toLowerCase();

// HTML-escape everything that comes from a comment: the Telegram node uses parse_mode HTML.
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const hasPlaceholder = /\[[^\]]{1,40}\]|<[^>]{1,40}>|\bxxx\b|to be completed|todo/i.test(response);
const commentNotFound = /not found \/ already inaccessible/i.test(status);
const metaFailed = /not posted|failed|error/i.test(status) && !commentNotFound;
const safetyRisk = d.safety_concern === true || category === 'safety';
const supportSignal = /(\border|deliver|shipping|shipped|parcel|package|tracking|refund|\breturn|warranty|guarantee|broken|damaged|defect|\bsupport\b)/i.test(lower);
const noResponseSignal = /(won['’]?t (even )?(answer|reply|respond)|don['’]?t (even )?(answer|reply|respond)|no response|never (answered|replied|responded)|nobody (answers|replies))/i.test(lower);
const purchaseSignal = /(\bbuy\b|\bpurchase\b|\bprice|how much|\bcost\b|how.*\border\b|\bto order\b)/i.test(lower) && !/don['’]?t buy|do not buy|never buy/i.test(lower);

const escalated = action === 'escalate';
const hiddenPersonalData = action === 'hide' && category === 'personal_data';
const hiddenWithCase = action === 'hide' && (supportSignal || noResponseSignal) && category !== 'abuse' && category !== 'spam';
const hiddenStrict = action === 'hide' && category === 'criticism';
const unanswered = action === 'ignore' && (supportSignal || purchaseSignal);

const shouldAlert = escalated || safetyRisk || metaFailed || hasPlaceholder || hiddenPersonalData || hiddenWithCase || hiddenStrict || unanswered;

function recommendation() {
  if (safetyRisk) return 'Safety concern: a person follows up privately. Do not discuss details in public, and do not hide or delete the comment.';
  if (metaFailed) return 'Check the comment ID and the Page token, then retry by hand if a reply or a hide is still needed.';
  if (hasPlaceholder) return 'The reply contains a placeholder. Edit or delete it by hand.';
  if (hiddenPersonalData) return 'Personal data was published and the comment is hidden. Contact the customer privately if a case is open.';
  if (hiddenWithCase || hiddenStrict) return 'Hidden comment that may contain a real customer case. Write to the customer privately or check support.';
  if (escalated && response) return 'A short polite reply was posted and the comment stays visible. Follow up privately; do not debate in public.';
  if (escalated) return 'Needs a human decision. The comment stays visible and no reply was posted.';
  if (unanswered) return 'A question or support request was not answered. Reply by hand.';
  if (commentNotFound) return 'The comment was already gone or inaccessible. Nothing to do.';
  return 'Review manually before acting.';
}

let severity = 'medium';
if (safetyRisk || metaFailed || hiddenPersonalData) severity = 'high';

const reasons = [
  escalated ? 'escalated for a human' : '',
  safetyRisk ? 'safety concern' : '',
  metaFailed ? 'reply or hide not confirmed by Meta' : '',
  hasPlaceholder ? 'placeholder in reply' : '',
  hiddenPersonalData ? 'personal data hidden' : '',
  hiddenWithCase ? 'hidden comment with a possible customer case' : '',
  hiddenStrict ? 'criticism hidden by STRICT_MODE' : '',
  unanswered ? 'question or support request not answered' : ''
].filter(Boolean).join(', ');

const alertMessage = `Comment alert\n\nPriority: ${severity}\nPlatform: ${esc(platform)}\nAuthor: ${esc(author)}\nComment ID: ${esc(comment_id || '(not found)')}\nStatus: ${esc(status)}\nDecision: ${esc(action)}${category ? ' / ' + esc(category) : ''}\n\nComment: ${esc(comment)}\n\nReply posted: ${esc(response || '(none)')}\n\nWhy flagged: ${esc(reasons)}\n\nSuggested next step: ${recommendation()}`;

return [{
  json: {
    ...row,
    qa_alert: shouldAlert,
    qa_severity: severity,
    qa_message: alertMessage,
    qa_recommendation: recommendation()
  }
}];

// Verifies the X-Hub-Signature-256 header: HMAC SHA-256 of the RAW request body, keyed with the Meta app secret.
// Needs: NODE_FUNCTION_ALLOW_BUILTIN=crypto, the "Raw Body" option on the POST webhook, and META_APP_SECRET.
const crypto = require('crypto');

const APP_SECRET = $env.META_APP_SECRET || '';
if (!APP_SECRET || APP_SECRET.startsWith('YOUR_')) {
  throw new Error('META_APP_SECRET is not set: refusing to process unsigned webhooks');
}

const item = $input.first();
const headers = item.json.headers || {};
const received = String(headers['x-hub-signature-256'] || '');

let raw = null;
try {
  raw = await this.helpers.getBinaryDataBuffer(0, 'data');
} catch (e) {
  raw = null;
}
if (!raw && item.binary?.data?.data) {
  try { raw = Buffer.from(item.binary.data.data, 'base64'); } catch (e) { raw = null; }
}
if (!raw) {
  throw new Error('Raw body not available: enable the Raw Body option on the POST webhook node');
}

const expected = 'sha256=' + crypto.createHmac('sha256', APP_SECRET).update(raw).digest('hex');
const a = Buffer.from(received);
const b = Buffer.from(expected);

// Invalid or missing signature: stop here, nothing downstream runs.
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  return [];
}

// Pass only the parsed body on. The raw binary is dropped.
return [{ json: { body: item.json.body } }];
